INSERT INTO `answer` VALUES ('dataset_cleaned_1_no_preprocessing','dataset_cleaned','No preprocessing or cleaning was done.'),('dataset_cleaned_2_preprocessed','dataset_cleaned','The data was preprocessed but not cleaned.'),('dataset_cleaned_3_cleaned_preprocessed','dataset_cleaned','Both cleaning and preprocessing were performed.'),('dataset_cleaned_4_cleaned','dataset_cleaned','The data was cleaned but no further preprocessing was done.'),('dataset_goal_no_better','dataset_goal','No, but no better datasets are available'),('dataset_goal_no_various','dataset_goal','No, the dataset can be used for various tasks'),('dataset_goal_yes_built_around','dataset_goal','Yes, and the model is built around this task'),('dataset_goal_yes_not_aligned','dataset_goal','Yes, but the model is not fully aligned with this task'),('dataset_sensitive_no','dataset_sensitive','No'),('dataset_sensitive_yes','dataset_sensitive','Yes'),('model_algorithm_no','model_algorithm','No'),('model_algorithm_partially','model_algorithm','Partially'),('model_algorithm_yes','model_algorithm','Yes'),('model_intended_user_no','model_intended_user','No'),('model_intended_user_yes','model_intended_user','Yes'),('model_intended_use_no','model_intended_use','No'),('model_intended_use_partially','model_intended_use','Partially'),('model_intended_use_yes','model_intended_use','Yes'),('model_user_benefits_no','model_user_benefits','No'),('model_user_benefits_yes','model_user_benefits','Yes'),('model_user_limitations_no','model_user_limitations','No'),('model_user_limitations_yes','model_user_limitations','Yes'),('no_explaination','output_explaination','No explanation'),('output_survey_no','output_survey','No'),('output_survey_yes','output_survey','Yes'),('yes_counterfactural','output_explaination','Yes, it proviedes conterfactual explanation'),('yes_global','output_explaination','Yes, it provides global explanation'),('yes_local','output_explaination','Yes, it provides local explanation');
