INSERT INTO `question` VALUES ('dataset_cleaned','Dataset','Was the data cleaned or preprocessed before model training?'),('dataset_goal','Dataset','Was the training dataset designed for a specific task or goal?'),('dataset_sensitive','Dataset','Does the dataset include potentially sensitive subgroups (e.g., age, gender, ethnicity)?'),('model_algorithm','Artificial Intelligence Model','Do you provide information about the machine learning algorithm used? \r\n'),('model_intended_use','Artificial Intelligence Model','Do you explain the intended use case for your model (which is, the problem it is designed to solve)?'),('model_intended_user','Artificial Intelligence Model','Have you described the intended users of your model (for example, developers, end-users, managers)?'),('model_user_benefits','Artificial Intelligence Model','Did you communicate the benefits of the AI system to users?'),('model_user_limitations','Artificial Intelligence Model','Did you communicate the technical limitations and potential risks of the AI system to users, such as its level of accuracy and/ or error rates?'),('output_explaination','Output','Does your model provide any explanation for predictions? If yes, what kind of explanation?'),('output_survey','Output','Do you continuously survey the users if they understand the decision(s) of the AI system? ');
